#!/usr/bin/env python3
"""The test_words_doors tests were split (TD-11c): the parts hold the checks and words_doors_common the shared helpers.
This module re-exports the names other tests import under the old name. It holds no check of its own: the canon
runs each part as its own process. `python -B test_words_doors.py --all` runs the parts one after the other.
"""
# split-shim: generated by tools/test_split.py
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
from harness import SCRIPTS, use_project
sys.path.insert(0, str(SCRIPTS))
from words_doors_common import (  # noqa: E402,F401
    TICKET,
    critic_review,
    critic_story,
    ctrl_project,
    plan_story,
    project_env,
    refused_text,
    s5_story,
    story_pipeline,
    story_with,
)

# the re-export is the point of this module: naming it in __all__ keeps it
__all__ = ["TICKET", "critic_review", "critic_story", "ctrl_project", "plan_story", "project_env", "refused_text", "s5_story", "story_pipeline", "story_with", "use_project"]

PARTS = ("test_words_doors_detector", "test_words_doors_doors", "test_words_doors_controller", "test_words_doors_flight_launcher")


def main() -> int:
    if "--all" not in sys.argv[1:]:
        print("test_words_doors.py: no checks of its own; they are in " + ", ".join(p + ".py" for p in PARTS))
        return 0
    here = Path(__file__).resolve().parent
    code = 0
    for part in PARTS:
        code = subprocess.run([sys.executable, "-B", str(here / (part + ".py"))]).returncode or code
    return code


if __name__ == "__main__":
    sys.exit(main())
